"use strict";

const crypto = require("crypto");

const PASSWORD_HASH_PREFIX = "scrypt";
const SCRYPT_COST = 16384;
const SCRYPT_BLOCK_SIZE = 8;
const SCRYPT_PARALLELIZATION = 1;
const PASSWORD_KEY_LENGTH = 64;

/**
 * Passwords set by users must meet the same requirements on all portals.
 * Initial passwords generated by SPHOT remain temporary and are changed on
 * first login; this policy applies to user-selected passwords.
 *
 * @param {string} password New password.
 * @return {boolean} Whether it meets the password policy.
 */
function isValidNewPassword(password) {
  return typeof password === "string" &&
    password.length >= 8 && password.length <= 256 &&
    /[A-Z]/.test(password) && /[a-z]/.test(password) &&
    /[0-9]/.test(password) && /[!@#?*-]/.test(password);
}

/**
 * @param {string} password Raw password.
 * @return {string} Versioned, salted scrypt hash.
 */
function hashPassword(password) {
  if (typeof password !== "string" || !password ||
      password.length > 256) {
    throw new Error("Invalid password");
  }
  const salt = crypto.randomBytes(16);
  const key = crypto.scryptSync(password, salt, PASSWORD_KEY_LENGTH, {
    N: SCRYPT_COST,
    r: SCRYPT_BLOCK_SIZE,
    p: SCRYPT_PARALLELIZATION,
    maxmem: 64 * 1024 * 1024,
  });
  return [PASSWORD_HASH_PREFIX, SCRYPT_COST, SCRYPT_BLOCK_SIZE,
    SCRYPT_PARALLELIZATION, salt.toString("base64"),
    key.toString("base64")].join("$");
}

/**
 * @param {string} encoded Versioned password hash.
 * @param {string} password Candidate password.
 * @return {boolean} Whether the candidate matches.
 */
function verifyPasswordHash(encoded, password) {
  if (typeof encoded !== "string" || typeof password !== "string" ||
      password.length > 256) return false;
  const parts = encoded.split("$");
  if (parts.length !== 6 || parts[0] !== PASSWORD_HASH_PREFIX ||
      parts[1] !== String(SCRYPT_COST) ||
      parts[2] !== String(SCRYPT_BLOCK_SIZE) ||
      parts[3] !== String(SCRYPT_PARALLELIZATION)) return false;
  try {
    const salt = Buffer.from(parts[4], "base64");
    const expected = Buffer.from(parts[5], "base64");
    if (salt.length !== 16 || expected.length !== PASSWORD_KEY_LENGTH) {
      return false;
    }
    const actual = crypto.scryptSync(password, salt, PASSWORD_KEY_LENGTH, {
      N: SCRYPT_COST,
      r: SCRYPT_BLOCK_SIZE,
      p: SCRYPT_PARALLELIZATION,
      maxmem: 64 * 1024 * 1024,
    });
    return crypto.timingSafeEqual(actual, expected);
  } catch (_) {
    return false;
  }
}

/**
 * Preserve logins for accounts that have not changed their initial password.
 * A hash, once present, always takes precedence over the legacy field.
 *
 * @param {Object} account Firestore account data.
 * @param {string} password Candidate password.
 * @return {boolean} Whether credentials match.
 */
function verifyAccountPassword(account, password) {
  if (typeof password !== "string" || !password) return false;
  if (typeof account.passwordHash === "string" && account.passwordHash) {
    return verifyPasswordHash(account.passwordHash, password);
  }
  const legacy = (account.temporaryPassword || "").toString();
  const a = Buffer.from(legacy);
  const b = Buffer.from(password);
  return a.length > 0 && a.length === b.length &&
    crypto.timingSafeEqual(a, b);
}

/**
 * Super Admin accounts are explicitly excluded from self-service recovery.
 * They can share the sauveteurAccounts collection and login screen.
 *
 * @param {Object} account Firestore account data.
 * @return {boolean} Whether it represents the Super Admin.
 */
function isSuperAdminAccount(account) {
  const roles = [account.role, account.userRole,
    ...(Array.isArray(account.fonctions) ? account.fonctions :
      [account.fonctions])];
  return roles.some((value) =>
    (value || "").toString().trim().toUpperCase() === "SUPER_ADMIN");
}

module.exports = {
  hashPassword,
  isSuperAdminAccount,
  isValidNewPassword,
  verifyAccountPassword,
  verifyPasswordHash,
};
